${pagingTop} SELECT homepage_id, group_idx, group_name, main_number, manager_name, work_number, user_phone, postcode, address_base, address_detailed, book_area, book_quantity, relay_plan, relay_personnel, receive_lib, approval_status, delete_yn, add_id, add_date FROM BOOK_RELAY_GROUP WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY group_idx DESC ${pagingBottom}

